.darma-loader-darma-b12-scanner-bed { --accent: var(--loader-color, #22d3ee); --accent-2: var(--loader-secondary-color, #3b82f6); width: var(--loader-size, 112px); height: calc(var(--loader-size, 112px) * .74); position: relative; overflow: hidden; border-radius: 7%; background: linear-gradient(#1e293b, #0b1220); box-shadow: inset 0 0 0 calc(var(--loader-size, 112px) * .028) #334155; }
.darma-loader-darma-b12-scanner-bed::before { content: ''; position: absolute; inset: 14% 15%; border-radius: 3px; background: repeating-linear-gradient(to bottom, color-mix(in srgb, #fff 24%, transparent) 0 7%, transparent 7% 20%); }
.darma-loader-darma-b12-scanner-bed::after { content: ''; position: absolute; top: -20%; left: -30%; width: 55%; height: 150%; transform: rotate(18deg); background: linear-gradient(90deg, transparent, rgba(255, 255, 255, .1), transparent); }
.darma-loader-darma-b12-scanner-bed .darma-loader-darma-b12-scanner-bed__bar { position: absolute; left: 0; width: 100%; height: 11%; background: linear-gradient(var(--accent), var(--accent-2)); box-shadow: 0 0 calc(var(--loader-size, 112px) * .1) var(--accent); animation: darma-loader-darma-b12-scanner-bed-scan calc(var(--loader-speed, 1s) * 2.4) ease-in-out infinite; }
@keyframes darma-loader-darma-b12-scanner-bed-scan { 0% { top: -11%; } 50% { top: 100%; } 100% { top: -11%; } }

